   dict(ad='Zeydiyye', ar='الزيدية', aralik='122/740 –', d='Zeyd b. Ali’ye nispet edilen, Şiî kollar içinde Sünnîlere en yakın kabul edilen mezhep. İmamın Hz. Ali soyundan, âlim ve zulme karşı kıyam eden biri olmasını şart koşar; mefdûlün imâmetini caiz görür. Kelâmda Mu‘tezile’ye yakındır; bugün başlıca Yemen’de yaşar.', temsilci=['Zeyd b. Ali', 'Kāsım er-Ressî', 'el-Hâdî ile’l-Hak', 'Ahmed b. Yahyâ b. el-Murtazâ', 'Şevkânî (Zeydî ortamdan)']),
   dict(ad='İsmâiliyye', ar='الإسماعيلية', aralik='II/VIII. yy sonu –', d='Ca‘fer es-Sâdık’tan sonra imâmetin İsmâil ve oğlu Muhammed ile devam ettiğine inanan; zâhir-bâtın ayrımı, te’vîl ve hiyerarşik davet teşkilatı ile tanınan Şiî kol. Fâtımî devletini kurdu; sonra Nizârî ve Müsta‘lî kollarına ayrıldı. Bugün Nizârîler Ağa Han’ı imam kabul eder, Müsta‘lî Bohralar ise Hindistan ve Yemen’de yaşar.', temsilci=['Kādî Nu‘mân', 'Ebû Ya‘kūb es-Sicistânî', 'Hamîdüddîn el-Kirmânî', 'Nâsır-ı Hüsrev', 'Hasan Sabbâh']),
   dict(ad='Mu‘tezile', ar='المعتزلة', aralik='II/VIII. yy – VI/XII. yy', d='Beş esas (tevhid, adl, va‘d-va‘îd, el-menzile beyne’l-menzileteyn, emr bi’l-ma‘rûf) etrafında aklı ön plana çıkaran kelâm ekolü. Basra ve Bağdat olmak üzere iki kola ayrıldı. Bağımsız bir topluluk olarak sürmese de görüşleri Zeydiyye ve İmâmiyye kelâmında yaşadı; modern dönemde de ilgi gördü.', temsilci=['Vâsıl b. Atâ', 'Amr b. Ubeyd', 'Ebü’l-Hüzeyl', 'Nazzâm', 'Câhiz', 'Kādî Abdülcebbâr']),
   dict(ad='Mürcie', ar='المرجئة', aralik='I/VII. yy sonu – IV/X. yy', d='Önce siyasî irca (Osman ve Ali hakkında hükmü erteleme), sonra ameli imandan ayıran itikadî bir tavır olarak gelişti. Horasan ve Mâverâünnehir’de Türklerin İslâmlaşmasında etkili oldu. Hanefî-Mâtürîdî gelenekle bağlantısı, muhaliflerin “Mürcie” adlandırması nedeniyle tartışmalıdır.', temsilci=['Hasan b. Muhammed b. el-Hanefiyye', 'Gaylân ed-Dımaşkī', 'Ebû Hanîfe (Mürcie-i sünne nitelemesiyle)']),
   dict(ad='Kerrâmiyye', ar='الكرامية', aralik='III–VII/IX–XIII. yy', d='Muhammed b. Kerrâm’ın zühd ve vaaz hareketi olarak Horasan’da başlayıp Gazneliler döneminde siyasî güce ulaşan fırka. Hankâh kurumuyla tasavvuf tarihinde de iz bıraktı. Moğol istilası sonrasında tarihten silindi.', temsilci=['Muhammed b. Kerrâm', 'İbnü’l-Heysam']),
