   dict(ad='Nusayriyye', ar='النصيرية', aralik='III/IX. yy –', d='Muhammed b. Nusayr’a nispet edilen, Hasîbî tarafından sistemleştirilen, öğretisini gizli tutan topluluk. Bugün Suriye ve Hatay-Adana çevresinde yaşar ve kendilerini çoğunlukla “Alevî” veya “Arap Alevî” olarak adlandırır. Anadolu Alevîliğinden ayrı bir tarihî ve itikadî yapıdır.', temsilci=['Muhammed b. Nusayr', 'Hüseyin b. Hamdân el-Hasîbî', 'Mekzûn es-Sincârî']),
